from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD format."""
    if yyyymmdd in (None, "", "00000000"):
        return None
    return datetime.strptime(yyyymmdd, "%Y%m%d").strftime("%Y-%m-%d")


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD format."""
    if iso in (None, ""):
        return "00000000"
    return datetime.strptime(iso, "%Y-%m-%d").strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N value to bool, treating blank as N."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units, half-up."""
    if amount is None or amount == "":
        return 0

    effective_currency = currency if currency not in (None, "") else "USD"
    exponent = 0 if effective_currency == "JPY" else 2
    scale = Decimal(10) ** exponent
    scaled = Decimal(str(amount)) * scale

    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
